    const fullPath = path.concat(lastName)

    if (!isArray) {
      const existing = table.entries.get(lastName)
      if (existing === undefined) {
        const t = newTable(true)
        table.entries.set(lastName, t)
        ctx.current.table = t
        ctx.current.path = fullPath
      } else if (existing.kind === 'table') {
        if (existing.headerDefined) this.err(`table ${fullPathStr(fullPath)} is defined twice`)
        existing.headerDefined = true
        ctx.current.table = existing
        ctx.current.path = fullPath
      } else {
        this.err(`${fullPathStr(fullPath)} is not a table`)
      }
    } else {
