      let arr
      if (existing === undefined) {
        arr = { kind: 'arrayoftables', items: [] }
        table.entries.set(lastName, arr)
      } else if (existing.kind === 'arrayoftables') {
        arr = existing
      } else {
        this.err(`${fullPathStr(fullPath)} is not an array of tables`)
