      if (node.items.length === 0) return '[]'
      const childIndent = indent + '  '
      const inner = node.items.map((it) => `${childIndent}${printJSON(it, childIndent)}`).join(',\n')
      return `[\n${inner}\n${indent}]`
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'integer':
      return node.value.toString()
    case 'float':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    default:
      throw new Error(`unknown node kind ${node.kind}`)
  }
}

export function toJSON(root) {
  return printJSON(root, '') + '\n'
}

function emitChildren(node, basePath, out) {
  if (node.kind === 'table') {
    const keys = sortedKeys(node.entries)
    for (const k of keys) {
      const child = node.entries.get(k)
      const path = basePath === '' ? k : `${basePath}.${k}`
      out.push(`${path} ${typeName(child)}`)
      emitChildren(child, path, out)
    }
